import java.util.*;

public class Test {

    public static void main(String[] args) {
        ArrayList<String> segments = new ArrayList<>();
        ArrayList<String> parenthesesSegments = new ArrayList<>();
        Scanner sc = new Scanner(System.in);
        int len = sc.nextInt();
        String str = sc.next();
        str += "^";
        int totalLen = len + 1;
        char[] buffer = new char[256];
        for (int i = 0; i < totalLen; i++) {
            buffer[i] = str.charAt(i);
        }
        int inParentheses = 0;
        String tempStr = "";
        for (int i = 0; i < totalLen; i++) {
            if (buffer[i] == '(') {
                inParentheses = 1;
                buffer[i] = '^';
                continue;
            } else if (buffer[i] == ')') {
                inParentheses = 0;
                parenthesesSegments.add(tempStr);
                buffer[i] = '^';
                tempStr = "";
            }
            if (inParentheses == 1) {
                tempStr += buffer[i];
                buffer[i] = '^';
            }
        }
        tempStr = "";
        for (int i = 0; i < totalLen; i++) {
            if (buffer[i] == '^') {
                if (tempStr.length() == 0) continue;
                segments.add(tempStr);
                tempStr = "";
            } else {
                tempStr += buffer[i];
            }
        }
        int maxLettersCount = 0;
        int totalWordsCount = 0;
        for (String segment : segments) {
            String s = segment + "_";
            int letterCount = 0;
            for (int j = 0; j < s.length(); j++) {
                if (Character.isLetter(s.charAt(j))) {
                    letterCount++;
                } else if (s.charAt(j) == '_') {
                    maxLettersCount = Math.max(maxLettersCount, letterCount);
                    letterCount = 0;
                }
            }
        }
        int wordsCount = 0;
        for (String content : parenthesesSegments) {
            String s = content + "_";
            String wordBuilder = "";
            for (int j = 0; j < s.length(); j++) {
                if (Character.isLetter(s.charAt(j))) {
                    wordBuilder += s.charAt(j);
                } else if (s.charAt(j) == '_' && !wordBuilder.isEmpty()) {
                    wordBuilder = "";
                    wordsCount++;
                }
            }
        }
        System.out.println(maxLettersCount + " " + wordsCount);
    }
}
